#include "stdlib/stats/base/ndarray/variancepn.h"
#include "stdlib/stats/strided/dvariancepn.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include <stdint.h>

// Blocksize for pairwise summation (NOTE: decreasing the blocksize decreases rounding error as more pairs are summed, but also decreases performance. Because the inner loop is unrolled eight times, the blocksize is effectively `16`.):
#define BLOCKSIZE 128

/**
* Returns an ndarray element as a double-precision floating-point number.
*
* ## Notes
*
* -   If provided an unsupported data type, the function returns `NaN`.
*
* @param dtype   data type
* @param ptr     pointer to an ndarray element
* @return        element value
*/
static double get_value( const int16_t dtype, const uint8_t *ptr ) {
	switch ( dtype ) {
	case STDLIB_NDARRAY_FLOAT64:
		return *(const double *)ptr;
	case STDLIB_NDARRAY_FLOAT32:
		return (double)( *(const float *)ptr );
	case STDLIB_NDARRAY_INT32:
		return (double)( *(const int32_t *)ptr );
	case STDLIB_NDARRAY_UINT32:
		return (double)( *(const uint32_t *)ptr );
	case STDLIB_NDARRAY_INT16:
		return (double)( *(const int16_t *)ptr );
	case STDLIB_NDARRAY_UINT16:
		return (double)( *(const uint16_t *)ptr );
	case STDLIB_NDARRAY_INT8:
		return (double)( *(const int8_t *)ptr );
	case STDLIB_NDARRAY_UINT8:
	case STDLIB_NDARRAY_UINT8C:
		return (double)( *(const uint8_t *)ptr );
	default:
		return 0.0 / 0.0; // NaN
	}
}

/**
* Returns the value of a zero-dimensional ndarray as a double-precision floating-point number.
*
* @param arr   input ndarray
* @return      element value
*/
static double get_scalar( const struct ndarray *arr ) {
	const uint8_t *ptr = stdlib_ndarray_data( arr ) + stdlib_ndarray_offset( arr );
	return get_value( stdlib_ndarray_dtype( arr ), ptr );
}

/**
* Computes the sum of ndarray elements using pairwise summation.
*
* ## Method
*
* -   This implementation uses pairwise summation, which has an `O(log n)` error bound (see Higham (1993)).
*
* @param N        number of indexed elements
* @param dtype    data type
* @param ptr      pointer to the first indexed element
* @param stride   stride length (in bytes)
* @return         output value
*/
static double sumpw( const int64_t N, const int16_t dtype, const uint8_t *ptr, const int64_t stride ) {
	int64_t M;
	int64_t n;
	int64_t i;
	double s0;
	double s1;
	double s2;
	double s3;
	double s4;
	double s5;
	double s6;
	double s7;
	double s;

	if ( N <= 0 ) {
		return 0.0;
	}
	if ( stride == 0 ) {
		return (double)N * get_value( dtype, ptr );
	}
	if ( N < 8 ) {
		// Use simple summation...
		s = get_value( dtype, ptr );
		ptr += stride;
		for ( i = 1; i < N; i++ ) {
			s += get_value( dtype, ptr );
			ptr += stride;
		}
		return s;
	}
	if ( N <= BLOCKSIZE ) {
		// Sum a block with 8 accumulators (by loop unrolling, we lower the effective blocksize to 16)...
		s0 = get_value( dtype, ptr );
		s1 = get_value( dtype, ptr+stride );
		s2 = get_value( dtype, ptr+(2*stride) );
		s3 = get_value( dtype, ptr+(3*stride) );
		s4 = get_value( dtype, ptr+(4*stride) );
		s5 = get_value( dtype, ptr+(5*stride) );
		s6 = get_value( dtype, ptr+(6*stride) );
		s7 = get_value( dtype, ptr+(7*stride) );
		ptr += 8 * stride;

		M = N % 8;
		for ( i = 8; i < N-M; i += 8 ) {
			s0 += get_value( dtype, ptr );
			s1 += get_value( dtype, ptr+stride );
			s2 += get_value( dtype, ptr+(2*stride) );
			s3 += get_value( dtype, ptr+(3*stride) );
			s4 += get_value( dtype, ptr+(4*stride) );
			s5 += get_value( dtype, ptr+(5*stride) );
			s6 += get_value( dtype, ptr+(6*stride) );
			s7 += get_value( dtype, ptr+(7*stride) );
			ptr += 8 * stride;
		}
		// Pairwise sum the accumulators:
		s = ( (s0+s1) + (s2+s3) ) + ( (s4+s5) + (s6+s7) );

		// Clean-up loop...
		for (; i < N; i++ ) {
			s += get_value( dtype, ptr );
			ptr += stride;
		}
		return s;
	}
	// Recurse by dividing by two, but avoiding non-multiples of unroll factor...
	n = N / 2;
	n -= n % 8;
	return sumpw( n, dtype, ptr, stride ) + sumpw( N-n, dtype, ptr+(n*stride), stride );
}

/**
* Computes the variance of a one-dimensional ndarray having an arbitrary real-valued data type using a two-pass algorithm.
*
* @param N            number of indexed elements
* @param correction   degrees of freedom adjustment
* @param dtype        data type
* @param ptr          pointer to the first indexed element
* @param stride       stride length (in bytes)
* @return             output value
*/
static double compute( const int64_t N, const double correction, const int16_t dtype, const uint8_t *ptr, const int64_t stride ) {
	int64_t i;
	double dN;
	double mu;
	double M2;
	double M;
	double n;
	double d;

	dN = (double)N;
	n = dN - correction;
	if ( N <= 0 || n <= 0.0 ) {
		return 0.0 / 0.0; // NaN
	}
	if ( N == 1 || stride == 0 ) {
		return 0.0;
	}
	// Compute an estimate for the mean:
	mu = sumpw( N, dtype, ptr, stride ) / dN;

	// Compute the variance...
	M2 = 0.0;
	M = 0.0;
	for ( i = 0; i < N; i++ ) {
		d = get_value( dtype, ptr ) - mu;
		M2 += d * d;
		M += d;
		ptr += stride;
	}
	return (M2/n) - ((M/dN)*(M/n));
}

/**
* Computes the variance of a one-dimensional ndarray using a two-pass algorithm.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray specifying the degrees of freedom adjustment.
*
* -   The function supports the following input ndarray data types: `float64`, `float32`, `int32`, `uint32`, `int16`, `uint16`, `int8`, `uint8`, and `uint8c`. If provided an ndarray having an unsupported data type, the function returns `NaN`.
*
* @param arrays   array containing a one-dimensional input ndarray and a zero-dimensional ndarray specifying the degrees of freedom adjustment
* @return         output value
*/
double stdlib_stats_variancepn( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const double correction = get_scalar( arrays[ 1 ] );
	const int16_t dtype = stdlib_ndarray_dtype( x );
	const int64_t N = stdlib_ndarray_dimension( x, 0 );

	// For double-precision floating-point ndarrays, delegate to the optimized strided kernel:
	if ( dtype == STDLIB_NDARRAY_FLOAT64 ) {
		return API_SUFFIX(stdlib_strided_dvariancepn_ndarray)( N, correction, (const double *)stdlib_ndarray_data( x ), stdlib_ndarray_stride_elements( x, 0 ), stdlib_ndarray_offset_elements( x ) );
	}
	// Otherwise, read each element as a double-precision floating-point number:
	return compute( N, correction, dtype, stdlib_ndarray_data( x ) + stdlib_ndarray_offset( x ), stdlib_ndarray_stride( x, 0 ) );
}
